$ErrorActionPreference='Stop';$root=Split-Path -Parent $PSScriptRoot;$script=Join-Path $root 'scripts\collect-privacy-proof.ps1';$out=Join-Path $env:TEMP 'beadwise-privacy-proof.json'
try{& $script -OutputPath $out;$r=Get-Content -Raw $out|ConvertFrom-Json;foreach($id in 'C-PRIVACY-001','C-PRIVACY-006'){if($id -notin @($r.probes.featureId)){throw "missing $id"}};if((Get-Content -Raw $out)-match [regex]::Escape($env:USERNAME)){throw 'account name leaked'};'PASS: privacy baseline and drift proof preserved policy/effective/unknown separation'}finally{Remove-Item $out -Force -ErrorAction SilentlyContinue}
